    return output[:limit].rstrip() + "\n\n[truncated for GUI]"


def format_duration(ms: int) -> str:
    seconds = max(1, round(ms / 1000))
    if seconds < 60:
        return f"{seconds}s"
    return f"{seconds // 60}m {seconds % 60:02d}s"


